import re, pathlib
rep = pathlib.Path(r"E:\Potential-gold\Zero-Day\docs\report")
t = (rep / "Chapter2_Literature_Review_v3_direct.md").read_text(encoding="utf-8")
body_md, _, maptab = t.partition("## Local-to-repo reference map")
# local->repo from map table
mp = {}
for m in re.finditer(r"^\| (\d+) \| .*? \| repo \[(\d+)\] \|", maptab, re.M):
    mp[m.group(1)] = m.group(2)
assert len(mp) == 40, len(mp)
# repo ref texts
repo = {}
for line in (rep / "References.md").read_text(encoding="utf-8").splitlines():
    m = re.match(r"\[(\d+)\]\s*(.*)", line)
    if m:
        repo[m.group(1)] = m.group(2).strip()
def tex_esc(s):
    s = s.replace("&", "\\&").replace("%", "\\%").replace("$", "\\$")
    return s
out = []
for para in body_md.split("\n\n"):
    p = para.strip()
    if not p:
        continue
    if p.startswith("## REVIEW"):
        continue
    if p.startswith("# CHAPTER"):
        continue
    m = re.match(r"### (2\.\d) (.*)", p)
    if m:
        out.append(f"\\section{{{tex_esc(m.group(2))}}}")
        continue
    if p.startswith("|"):
        rows = [r.split("|")[1:-1] for r in p.splitlines() if r.strip().startswith("|")]
        cells = [[tex_esc(c.strip()) for c in r] for r in rows]
        ncol = len(cells[0])
        out.append("\\begin{center}\n\\begin{tabular}{" + "l" * ncol + "}\n\\toprule")
        hdr_done = False
        for r in cells:
            if all(set(c) <= set(":- ") for c in r):
                out.append("\\midrule")
                hdr_done = True
                continue
            out.append(" & ".join(r) + " \\\\")
        out.append("\\bottomrule\n\\end{tabular}\n\\end{center}")
        continue
    if "<img " in p:
        m = re.search(r'src="([^"]+)"', p)
        fn = m.group(1).replace("figures/", "")
        out.append(f"\\begin{{figure}}[H]\n\\centering\n\\includegraphics[width=0.9\\textwidth]{{../report/figures/{fn}}}\n\\end{{figure}}")
        continue
    if p.startswith("<p "):
        txt = re.sub(r"<[^>]+>", "", p).strip()
        if not txt:
            continue
        if txt.startswith("Table ") or txt.startswith("Fig. "):
            out.append("\\begin{center}\\textbf{" + tex_esc(txt) + "}\\end{center}")
        elif txt.startswith("Source:"):
            out.append("{\\small\\textit{" + tex_esc(txt) + "}}")
        else:
            out.append(tex_esc(txt))
        continue
    out.append(p)
# cites [N] -> \cite{kN}
tex = "\n\n".join(out)
tex = re.sub(r"\[(\d{1,2})\]", lambda m: "\\cite{k" + m.group(1) + "}", tex)
bib = ["\\begin{thebibliography}{40}"]
for i in range(1, 41):
    r = repo[mp[str(i)]]
    r = tex_esc(r)
    bib.append(f"\\bibitem{{k{i}}} {r}")
bib.append("\\end{thebibliography}")
d = rep / "ch2_v3"
(d / "ch2_body.tex").write_text(tex + "\n\n" + "\n".join(bib) + "\n", encoding="utf-8")
print("ch2_body.tex written,", len(tex.split()), "words")

